/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */
import { readFileSync } from 'node:fs'
import { parse } from './parse.js'
import { count } from './count.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'rounds' && args[0] !== 'tally')) fail('usage: cli.js rounds|tally')

let election
try {
  election = parse(readFileSync(0, 'utf8'))
} catch (e) {
  if (e && e.election) fail(e.message)
  throw e
}

const result = count(election)
let out = ''
if (args[0] === 'rounds') out += result.lines.join('\n') + '\n'
else out += `rounds ${result.rounds}\n`
out += result.winner === null ? 'no winner\n' : `winner ${result.winner}\n`
process.stdout.write(out)
"}

