{"file_path":"src/parse.js","content":"/** Parses election text into { candidates, ballots: [{count: bigint, ranking}] }. */
function bad(message) {
  const e = new Error(message)
  e.election = true
  return e
}

const NAME = /^[A-Za-z0-9_-]+$/

export function parse(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  let candidates = null
  const ballots = []
  lines.forEach((raw, i) => {
    const n = i + 1
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const words = line.split(/\s+/)
    const word = words[0]
    if (word === 'candidates') {
      if (candidates !== null) throw bad(`line ${n}: candidates must be declared once, before any ballot`)
      if (words.length < 2) throw bad(`line ${n}: expected candidates <name>...`)
      const seen = new Set()
      for (const name of words.slice(1)) {
        if (!NAME.test(name)) throw bad(`line ${n}: invalid candidate name ${name}`)
        if (seen.has(name)) throw bad(`line ${n}: candidate ${name} is declared twice`)
        seen.add(name)
      }
      candidates = [...seen]
    } else if (word === 'ballot') {
      if (candidates === null) throw bad(`line ${n}: candidates must be declared once, before any ballot`)
      if (words.length < 3) throw bad(`line ${n}: expected ballot <count> <candidate>...`)
      if (!/^[1-9][0-9]*$/.test(words[1])) throw bad(`line ${n}: count must be a positive integer`)
      const seen = new Set()
      for (const name of words.slice(2)) {
        if (!candidates.includes(name)) throw bad(`line ${n}: unknown candidate ${name}`)
        if (seen.has(name)) throw bad(`line ${n}: candidate ${name} is repeated`)
        seen.add(name)
      }
      ballots.push({ count: BigInt(words[1]), ranking: words.slice(2) })
    } else {
      throw bad(`line ${n}: unknown directive ${word}`)
    }
  })
  if (candidates === null) throw bad('no candidates')
  return { candidates, ballots }
}
"}

